#!/usr/bin/env python3
import socket
import concurrent.futures

def test_port(port):
    try:
        sock = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
        sock.settimeout(10)
        result = sock.connect_ex(("34.234.204.29", port))
        if result == 0:
            print(f"[+] Port {port} is open")
            return port
        sock.close()
    except:
        pass
    return None

def scan_ports():
    ports = range(39069, 39090)  # Test ports 39079 ±10
    with concurrent.futures.ThreadPoolExecutor(max_workers=10) as executor:
        results = list(executor.map(test_port, ports))
    return [p for p in results if p is not None]

if __name__ == "__main__":
    print("[*] Scanning ports around 39079...")
    open_ports = scan_ports()
    if not open_ports:
        print("[-] No open ports found in range")

